import { Actor, Document } from './types';
import { DocumentRepository } from './repository';
export class DocumentService {
  constructor(private readonly repository: DocumentRepository) {}
  archive(actor: Actor, id: string): void {
    const document = this.repository.find(id);
    // Missing, deleted and foreign-tenant documents are all reported as not found, even for admins.
    if (!document || document.deleted || document.tenant !== actor.tenant) throw new Error('not found');
    // Permission is checked before the no-op path so an already-archived document still requires it.
    if (!canArchive(actor, document)) throw new Error('forbidden');
    if (document.archived) return;
    this.repository.archive(document, actor.user);
  }
}
function canArchive(actor: Actor, document: Document): boolean {
  switch (actor.role) {
    case 'admin': return true;
    case 'editor': return document.owner === actor.user;
    default: return false; // viewer, and any unknown role, may never archive
  }
}
