        // Authorization matrix for DocumentService.archive.
        const seed = () => [
          { id: 'mine', tenant: 'a', owner: 'u', deleted: false, archived: false },
          { id: 'theirs', tenant: 'a', owner: 'x', deleted: false, archived: false },
          { id: 'gone', tenant: 'a', owner: 'u', deleted: true, archived: false },
          { id: 'foreign', tenant: 'b', owner: 'u', deleted: false, archived: false },
          { id: 'done', tenant: 'a', owner: 'x', deleted: false, archived: true },
        ];
        const fresh = () => { const r = new DocumentRepository(seed()); return { repo: r, svc: new DocumentService(r) }; };
        const snap = (repo) => JSON.stringify({ docs: repo.documents, audit: repo.audit });
        const actor = (role, user = 'u', tenant = 'a') => ({ tenant, user, role });

        // Success: exact audit entry, only the target changes.
        { const { repo, svc } = fresh(); svc.archive(actor('admin'), 'theirs');
          assert.deepStrictEqual(repo.audit, [{ actor: 'u', document: 'theirs' }]);
          assert.deepStrictEqual(repo.documents.map(d => d.archived), [false, true, false, false, true]); }
        { const { repo, svc } = fresh(); svc.archive(actor('editor'), 'mine');
          assert.deepStrictEqual(repo.audit, [{ actor: 'u', document: 'mine' }]);
          assert.equal(repo.documents[0].archived, true); }

        // Not found: missing, deleted and foreign-tenant, for every role including admin.
        for (const role of ['admin', 'editor', 'viewer']) {
          for (const id of ['missing', 'gone', 'foreign']) {
            const { repo, svc } = fresh(); const before = snap(repo);
            assert.throws(() => svc.archive(actor(role), id), (e) => e instanceof Error && e.message === 'not found', `${role} ${id}`);
            assert.equal(snap(repo), before);
          }
        }

        // Forbidden: visible but not permitted.
        for (const [role, id] of [['viewer', 'mine'], ['viewer', 'theirs'], ['viewer', 'done'], ['editor', 'theirs']]) {
          const { repo, svc } = fresh(); const before = snap(repo);
          assert.throws(() => svc.archive(actor(role), id), (e) => e instanceof Error && e.message === 'forbidden', `${role} ${id}`);
          assert.equal(snap(repo), before);
        }

        // Already archived: permission still enforced first; allowed repeats are silent no-ops.
        { const { repo, svc } = fresh(); const before = snap(repo);
          svc.archive(actor('admin'), 'done'); assert.equal(snap(repo), before); }
        { const { repo, svc } = fresh(); const before = snap(repo);
          assert.throws(() => svc.archive(actor('editor'), 'done'), /forbidden/); assert.equal(snap(repo), before); }
        { const { repo, svc } = fresh(); svc.archive(actor('editor'), 'mine'); const before = snap(repo);
          svc.archive(actor('editor'), 'mine'); assert.equal(snap(repo), before); assert.equal(repo.audit.length, 1); }

        // Actor tenant must match: admin of another tenant cannot see tenant a documents.
        { const { repo, svc } = fresh(); const before = snap(repo);
          assert.throws(() => svc.archive(actor('admin', 'z', 'b'), 'mine'), /not found/); assert.equal(snap(repo), before); }
        console.log('archive authorization checks passed');
